#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# cirnonine.com 部署向导（issue #3，ADR-0001、ADR-0003）。
# 已经做完的步骤会被自动检测并跳过，所以中途 Ctrl-C 之后可以直接重跑。

REPO="ciron-nine/cirnonine.com"
APEX="cirnonine.com"
MEDIA_HOST="media.$APEX"
DASH="https://dash.cloudflare.com/?to=/:account"
NAMESILO_DOMAINS="https://www.namesilo.com/account_domains.php"
PREVIEW_BRANCH="wizard/preview-check"
CHECKS=()   # 验证通过的项目，最后汇总

# passed "描述" 打印一行 ✓，并记进最后的“验证通过”汇总。
passed() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; CHECKS+=("$1"); }

# dns NAME TYPE 打印公共 DNS 的应答（DNS-over-HTTPS）。不用 dig：本机代理的
# fake-ip 模式会把 dig 的结果换成 198.18.x.x。查询本身失败时返回非零。
dns() {
  local json
  json=$(curl -sf --max-time 15 -H 'accept: application/dns-json' \
    "https://cloudflare-dns.com/dns-query?name=$1&type=$2") || return 1
  # 只取 Answer 段：查不到时 Authority 段里的 SOA 也带 "data"，不能算作应答。
  sed -n 's/.*"Answer":\[\([^]]*\)\].*/\1/p' <<<"$json" \
    | grep -o '"data":"[^"]*"' | cut -d'"' -f4 || true
}

# http_probe URL 打印 "状态码 跳转地址 内容类型"（不跟随跳转）。
http_probe() {
  curl -s -o /dev/null --max-time 30 \
    -w '%{http_code} %{redirect_url} %{content_type}' "$1" || true
}

# wait_for "描述" 检查命令…：检查不通过就让人按 Enter 重试，或输入 s 跳过。
# 跳过的项目记进最后的“还要手动做”清单。
wait_for() {
  local what="$1" reply=""; shift
  while true; do
    if "$@"; then passed "$what"; return 0; fi
    warn "还没好：$what"
    printf '  %sEnter 重新检查，s 跳过（以后重跑本脚本再验）%s ' "$DIM" "$RESET"
    read -r reply || reply=s
    if [[ "$reply" =~ ^[Ss] ]]; then SKIPPED+=("$what"); return 1; fi
  done
}

# http_ok URL：返回 200。
http_ok() { [[ "$(http_probe "$1")" == 200\ * ]]; }

ns_on_cloudflare() { dns "$APEX" NS | grep -q '\.ns\.cloudflare\.com\.$'; }
# DNS 查询成功且没有 DS 记录；查询失败时也返回非零，宁可多提示一次。
ds_confirmed_absent() { local ds; ds=$(dns "$APEX" DS) && [[ -z "$ds" ]]; }
pages_dev_up()     { http_ok "https://$PAGES_PROJECT.pages.dev/"; }
apex_up()          { http_ok "https://$APEX/"; }
www_redirects() {
  [[ "$(http_probe "https://www.$APEX/wizard-check?x=1")" == "301 https://$APEX/wizard-check?x=1 "* ]]
}
media_resolves()   { [[ -n "$(dns "$MEDIA_HOST" A)" ]]; }
media_serves()     { http_ok "https://$MEDIA_HOST/$TEST_AUDIO_KEY"; }

# ask_cf_ns KEY "提示"：读一个 Cloudflare nameserver，直到格式对为止。
ask_cf_ns() {
  ask "$1" "$2"
  until [[ "${!1}" == *.ns.cloudflare.com ]]; do warn "应该以 .ns.cloudflare.com 结尾"; ask "$1" "$2"; done
}

PREVIEW_URL=""
pr_has_preview() {
  PREVIEW_URL=$(gh pr view "$PR_URL" --repo "$REPO" --json comments --jq '.comments[].body' 2>/dev/null \
    | grep -o 'https://[A-Za-z0-9.-]*\.pages\.dev' | head -n1 || true)
  [[ -n "$PREVIEW_URL" ]]
}

run_wizard() {

TOTAL_STAGES=14

cd "$(git rev-parse --show-toplevel)"   # .env 和 git 操作都以仓库根目录为准

banner "cirnonine.com 部署：Cloudflare Pages、域名与 R2"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "开始之前"
say "检查本机工具和仓库状态。"
for tool in curl git gh; do
  command -v "$tool" >/dev/null 2>&1 || { warn "缺少 $tool，请先安装再重跑"; exit 1; }
done
if gh auth status >/dev/null 2>&1; then passed "gh 已登录"
else warn "gh 未登录：最后一步要用它开测试 PR。先运行 gh auth login 再重跑"; exit 1; fi
git fetch -q origin main
if git cat-file -e origin/main:.node-version 2>/dev/null; then
  passed "main 上有 .node-version（Node $(git show origin/main:.node-version)）"
else
  warn "origin/main 上还没有 .node-version：Cloudflare 会用它的默认 Node，可能低于 Astro 的要求"
  confirm "仍然继续？" || exit 1
fi
PNPM_VERSION=$(grep -o '"packageManager": *"pnpm@[^"]*"' package.json | sed 's/.*pnpm@//; s/"$//' || true)
if [[ -n "$PNPM_VERSION" ]]; then passed "package.json 指定 pnpm $PNPM_VERSION"
else warn "package.json 里没有 \"packageManager\": \"pnpm@…\"，无法确定 Cloudflare 该用的 pnpm 版本"; exit 1; fi
note "下面每一步都会打开 Cloudflare / NameSilo 后台。按钮名按英文界面写。"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "NameSilo：关闭 DNSSEC"
if ns_on_cloudflare; then
  passed "nameserver 已经是 Cloudflare 的，跳过"
elif ds_confirmed_absent; then
  passed "$APEX 没有 DS 记录，不用关"
else
  warn "$APEX 开着 DNSSEC。带着它换 nameserver 会让域名解析失败，必须先关。"
  open_url "$NAMESILO_DOMAINS"
  step "Domain Manager → 点 $APEX 进入域名详情 → DNSSEC 那一行的 DS Records 管理"
  step "删掉所有 DS 记录并保存（说明：https://www.namesilo.com/support/v2/articles/domain-manager/ds-records）"
  note "等域名迁到 Cloudflare 之后，可以在 Cloudflare 里重新开启 DNSSEC。"
  wait_for "$APEX 的 DS 记录已删除" ds_confirmed_absent || true
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare：添加 $APEX 站点"
if ns_on_cloudflare; then
  passed "$APEX 已经由 Cloudflare 托管（$(dns "$APEX" NS | tr '\n' ' ')），跳过"
else
  open_url "$DASH/domains/overview"
  step "Onboard a domain → 输入 $APEX → 选择 Quick scan for DNS records → Continue"
  step "计划选 Free → Continue"
  step "检查扫描出来的 DNS 记录：删掉 $APEX 和 www 指向 NameSilo 停放页的 A / AAAA / CNAME 记录"
  note "（后面 Pages 会自己创建裸域名记录，www 记录也由本向导来建；留着旧记录会让网站报 522。）"
  step "继续到最后一页，记下 Cloudflare 分配给你的两个 nameserver（形如 xxx.ns.cloudflare.com）"
  ask_cf_ns CF_NS1 "第一个 nameserver："
  ask_cf_ns CF_NS2 "第二个 nameserver："
  write_env CF_NS1 "$CF_NS1"
  write_env CF_NS2 "$CF_NS2"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "NameSilo：把 nameserver 换成 Cloudflare 的"
if ns_on_cloudflare; then
  passed "nameserver 已经是 Cloudflare 的，跳过"
else
  warn "提交之后，$APEX 的 DNS 就由 Cloudflare 回答了；NameSilo 里的 DNS 记录不再生效。"
  open_url "$NAMESILO_DOMAINS"
  step "Domain Manager → 勾选 $APEX → 顶部工具栏的 Change Nameservers（或进入域名详情 → NameServers 一行的 Change）"
  step "NameServer 1 填 ${CF_NS1:-Cloudflare 站点 Overview 页上的第一个 nameserver}"
  step "NameServer 2 填 ${CF_NS2:-Cloudflare 站点 Overview 页上的第二个 nameserver}"
  step "清空其余的 NameServer 栏（默认的 dnsowl.com）→ Submit"
  note "生效要几分钟到 24 小时。不用干等：下一步先建 Pages 项目，第 6 步再回来检查。"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare Pages：创建项目并连接 GitHub"
PAGES_PROJECT=$(_existing PAGES_PROJECT || echo cirnonine)
if pages_dev_up; then
  passed "https://$PAGES_PROJECT.pages.dev 已经能打开，跳过"
else
open_url "$DASH/workers-and-pages"
step "Create application → Pages → Connect to Git → GitHub"
warn "Create application 默认是 Workers 的导入流程：页面上出现 Deploy command 一栏就说明进错了，回去切到 Pages（Pages 标签，或底部的 Looking to deploy Pages? Get started）"
step "GitHub 授权页安装 Cloudflare Pages：选 Only select repositories → $REPO → Install & Authorize"
step "回到 Cloudflare，选中 $REPO → Begin setup"
step "Project name 填 cirnonine（决定 cirnonine.pages.dev 和 PR 预览地址）；Production branch 选 main"
step "Framework preset 选 Astro；Build command 填 pnpm build；Build output directory 填 dist"
step "Environment variables 加一条：PNPM_VERSION = $PNPM_VERSION"
note "（Cloudflare 的构建镜像不会从 lockfile 推断 pnpm 版本；Node 版本已由仓库里的 .node-version 指定。）"
step "Save and Deploy，等构建日志结束并显示成功"
ask PAGES_PROJECT "你填的 Project name（直接回车 = cirnonine）："
PAGES_PROJECT="${PAGES_PROJECT:-cirnonine}"
write_env PAGES_PROJECT "$PAGES_PROJECT"
note "构建失败时看 Deployments 里那次部署的日志；修好推到 main 会自动重试。"
wait_for "https://$PAGES_PROJECT.pages.dev 能打开" pages_dev_up || true
note "之后到项目 Settings 的环境变量部分确认 Production 和 Preview 都有 PNPM_VERSION。"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "等待 $APEX 在 Cloudflare 生效"
say "检查公共 DNS 上 $APEX 的 nameserver 是否已经是 Cloudflare 的。"
note "Cloudflare 后台该站点的 Overview 显示 Active 时也说明好了；生效时还会发邮件。"
wait_for "$APEX 的 nameserver 指向 Cloudflare" ns_on_cloudflare || true
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Pages：绑定 $APEX"
if apex_up; then
  passed "https://$APEX 已经能打开，跳过"
else
  open_url "$DASH/:zone/dns/records"
  step "选 $APEX → DNS Records：如果有 Name 为 $APEX 的 A / AAAA / CNAME 记录，先删掉"
  note "（这些是从 NameSilo 扫描过来的旧记录，现在访问 $APEX 报 522 就是它们。Pages 会自己建一条 CNAME。）"
  pause "删完（或本来就没有）后按 Enter"
  open_url "$DASH/workers-and-pages"
  step "进入 $PAGES_PROJECT → Custom domains → Set up a domain"
  step "输入 $APEX → Continue → Activate domain"
  note "状态变成 Active 要几分钟（要签发证书）。"
  wait_for "https://$APEX 能打开" apex_up || true
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "www 跳转：创建 Bulk Redirect 规则"
if www_redirects; then
  passed "www 已经 301 跳转到裸域名，跳过"
else
  open_url "$DASH/bulk-redirects"
  step "Create Bulk Redirect List → 名字填 www_to_apex → Next"
  step "Or, manually add URL redirects：Source URL 填 www.$APEX，Target URL 填 https://$APEX，Status 选 301"
  step "展开 Edit parameters，勾选 Preserve query string、Subpath matching、Preserve path suffix、Include subdomains → Next → Next"
  step "Continue to Redirect Rules → Rule name 填 www to apex → 选 www_to_apex → Save and Deploy"
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "www 跳转：添加 www 的 DNS 记录"
if www_redirects; then
  passed "www 已经 301 跳转到裸域名，跳过"
else
  open_url "$DASH/:zone/dns/records"
  step "选 $APEX → Add record：Type A，Name www，IPv4 address 192.0.2.1，Proxy status 打开（橙色云）→ Save"
  note "（192.0.2.1 只是占位地址：请求在 Cloudflare 边缘就被跳转了。已有 www 记录就改成这样。）"
  wait_for "https://www.$APEX/… 301 跳到 https://$APEX/…（保留路径和参数）" www_redirects || true
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "R2：开通并创建存音频的桶"
open_url "$DASH/r2/overview"
step "第一次用 R2 的话，按页面提示完成 checkout 开通 R2 订阅（有免费额度，但要绑付款方式，你自己填）"
step "Create bucket → Bucket name 填 cirnonine-media → 位置保持默认 → Create bucket"
note "不要开启 r2.dev 公共访问；音频只通过 $MEDIA_HOST 访问。"
ask R2_BUCKET "你填的 Bucket name（直接回车 = cirnonine-media）："
R2_BUCKET="${R2_BUCKET:-cirnonine-media}"
write_env R2_BUCKET "$R2_BUCKET"
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "R2：绑定 $MEDIA_HOST"
if media_resolves; then
  passed "$MEDIA_HOST 已经有 DNS 记录，跳过"
else
  open_url "$DASH/r2/overview"
  step "进入 $R2_BUCKET → Settings → Custom Domains → Add"
  step "输入 $MEDIA_HOST → Continue → 确认要添加的 DNS 记录 → Connect Domain"
  note "状态从 Initializing 变成 Active 要几分钟；一直不变就点该域名旁的 … → Retry connection。"
  wait_for "$MEDIA_HOST 解析到 Cloudflare" media_resolves || true
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "R2：上传测试音频并通过 $MEDIA_HOST 访问"
TEST_AUDIO_KEY="wizard-test.m4a"
TEST_DIR=$(mktemp -d)
# 库里的 say() 会遮住 macOS 的 say 命令，所以用 command 绕过函数。
if command -v say >/dev/null 2>&1 \
  && command say -o "$TEST_DIR/$TEST_AUDIO_KEY" --file-format=m4af --data-format=aac "cirno nine media test" 2>/dev/null \
  && [[ -s "$TEST_DIR/$TEST_AUDIO_KEY" ]]; then
  say "已生成测试音频：$TEST_DIR/$TEST_AUDIO_KEY"
  command -v open >/dev/null 2>&1 && open -R "$TEST_DIR/$TEST_AUDIO_KEY" 2>/dev/null || true
else
  say "随便挑一个本地音频文件当测试文件。"
  ask TEST_AUDIO_KEY "它的文件名（上传后的对象名，例如 test.mp3）："
fi
open_url "$DASH/r2/overview"
step "进入 $R2_BUCKET → Upload → 选这个文件，直接放在桶的根目录（不要放进文件夹）"
wait_for "https://$MEDIA_HOST/$TEST_AUDIO_KEY 能访问" media_serves || true
note "状态码、跳转、Content-Type：$(http_probe "https://$MEDIA_HOST/$TEST_AUDIO_KEY")"
note "验证完可以在 R2 里删掉 $TEST_AUDIO_KEY。"
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "验证：push 到 main 自动上线"
git fetch -q origin main
MAIN_SHA=$(git rev-parse --short origin/main)
say "main 最新提交：$MAIN_SHA $(git log -1 --format=%s origin/main)"
open_url "$DASH/workers-and-pages"
step "进入 $PAGES_PROJECT → Deployments，看最上面的 Production 部署"
note "第 5 步的 Save and Deploy 是手动触发的，不能证明 push 会自动部署；要看到一次在建项目之后 push 触发的部署才算。"
if confirm "最上面的 Production 部署是 $MAIN_SHA，且是建项目之后 push 触发的？"; then
  passed "push 到 main 自动部署（$MAIN_SHA）"
  if apex_up; then passed "https://$APEX 显示最新构建"; else SKIPPED+=("https://$APEX 还打不开"); fi
else
  SKIPPED+=("下次 push 到 main 后重跑本脚本，确认 Pages 自动部署了那次提交")
fi
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "验证：PR 出现 Cloudflare 预览地址"
say "开一个只含空提交的临时 PR（分支 $PREVIEW_BRANCH），看 Cloudflare 是否贴出预览地址。"
say "不会改动你本地的分支和工作区。"
if confirm "推送 $PREVIEW_BRANCH 并开这个临时 PR？"; then
  PREVIEW_SHA=$(git commit-tree "origin/main^{tree}" -p origin/main -m "chore: 部署向导的预览检查（验证后关闭）")
  git push -q -f origin "$PREVIEW_SHA:refs/heads/$PREVIEW_BRANCH"
  PR_URL=$(gh pr list --repo "$REPO" --head "$PREVIEW_BRANCH" --state open --json url --jq '.[0].url // empty')
  if [[ -z "$PR_URL" ]] && ! PR_URL=$(gh pr create --repo "$REPO" --base main --head "$PREVIEW_BRANCH" \
      --title "chore: 部署向导的预览检查" \
      --body "由 scripts/setup-deploy.sh 创建，用来确认 Cloudflare Pages 会给 PR 生成预览地址。验证后关闭。"); then
    git push -q origin --delete "$PREVIEW_BRANCH" || true
    warn "创建 PR 失败，已删除远端分支 $PREVIEW_BRANCH"
    PR_URL=""
  fi
fi
if [[ -n "${PR_URL:-}" ]]; then
  open_url "$PR_URL"
  note "Cloudflare Pages 会在 PR 里评论预览地址，构建要一两分钟。"
  if wait_for "PR 上出现 Cloudflare 预览地址" pr_has_preview; then
    say "预览地址：$PREVIEW_URL"
  fi
  if confirm "关闭这个临时 PR 并删除 $PREVIEW_BRANCH？"; then
    if gh pr close "$PR_URL" --repo "$REPO" --delete-branch >/dev/null; then
      passed "已关闭临时 PR 并删除分支"
    else
      SKIPPED+=("关闭临时 PR 并删除分支：$PR_URL")
    fi
  else
    SKIPPED+=("关闭临时 PR：$PR_URL")
  fi
else
  SKIPPED+=("确认新开 PR 时出现 Cloudflare 预览地址")
fi
pause

finish
if (( ${#CHECKS[@]} )); then
  printf '  %s验证通过：%s\n' "$BOLD" "$RESET"
  for c in "${CHECKS[@]}"; do note "  ✓ $c"; done
  printf '\n'
fi
}

run_wizard "$@"; exit
